"""Snapping span edges to a fixed step, for payroll."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span


def check_step(step: int) -> None:
    """Steps must be positive and divide an hour evenly."""
    if step <= 0:
        raise ValueError(f"step must be positive: {step}")
    if 60 % step:
        raise ValueError(f"step must divide 60: {step}")


def round_minutes(value: int, step: int) -> int:
    """Nearest multiple of step, with halves going up."""
    return (value + step // 2) // step * step


def round_span(span: Span, step: int) -> Span:
    """Snap both edges; ValueError if the span vanishes."""
    check_step(step)
    return Span(
        round_minutes(span.start, step),
        round_minutes(span.end, step)
    )


def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    hours, extra = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {extra}m)"


def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, in order, after rounding."""
    check_step(step)
    rounded = [round_span(item, step) for item in spans]
    return [span_label(item) for item in rounded]

