import unittest

from hourglass.models import Span
from hourglass.rounding import (
    round_minutes,
    round_span,
    rounded_labels,
    span_label
)


class RoundMinutesTests(unittest.TestCase):
    def test_nearest(self):
        self.assertEqual(round_minutes(62, 15), 60)
        self.assertEqual(round_minutes(68, 15), 75)

    def test_half_goes_up(self):
        self.assertEqual(round_minutes(5, 10), 10)
        self.assertEqual(round_minutes(25, 10), 30)
        self.assertEqual(round_minutes(15, 30), 30)


class LabelTests(unittest.TestCase):
    def test_label(self):
        label = span_label(Span(540, 1035))
        self.assertEqual(label, "09:00-17:15 (8h 15m)")

    def test_whole_hours_keep_minutes(self):
        label = span_label(Span(540, 600))
        self.assertEqual(label, "09:00-10:00 (1h 0m)")


class RoundedLabelTests(unittest.TestCase):
    def test_rounds_each_span(self):
        spans = [Span(543, 1032), Span(600, 640)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "10:00-10:45 (0h 45m)"]
        )

    def test_empty(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_end_can_reach_midnight(self):
        label = rounded_labels([Span(1380, 1439)], 15)
        self.assertEqual(label, ["23:00-24:00 (1h 0m)"])

    def test_vanishing_span_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(601, 604)], 15)

    def test_round_span(self):
        result = round_span(Span(61, 119), 30)
        self.assertEqual(result, Span(60, 120))


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(60, 120)], step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 6, 10, 12, 15, 20, 30, 60):
            with self.subTest(step=step):
                rounded_labels([Span(0, 1440)], step)
